rows[90968]={title={{22,717541017},"바로크식 칼집"},description={{228,849610085},"기분 나쁘게 장식된 칼집입니다. 눈에 보이는 부분은 죄다 조각했거나 금박을 입혔거나 글씨를 새겨 놓았습니다. 이 칼집에는 아마도 매우 강력한 마법이나 의식과 관련된 무기가 담겨 있던 것 같습니다."}}
