rows[90974]={title={{23,1265394046},"고급 수정 가지촛대"},description={{204,1937167665},"열두 개의 양초를 올릴 수 있게 만든 촛대입니다. 파란색과 보라색의 수정을 연결하는 얇은 사슬과 화려한 소용돌이 장식이 드리워져 있습니다. 바닥에는 전문 세공인의 머리글자 V.T.가 새겨져 있습니다."}}
rows[90975]={title={{18,1085256722},"위엄 깃든 초상화"},description={{294,1252619071},"매우 진지한 드레나이 신사를 엄숙하게 그려 놓은 유화입니다. 전체적으로 인물이 돋보이지만, 맨 아랫부분에 신사가 바지를 입고 있지 않은 것으로 보아 화가는 상대방을 꽤 우습게 생각했음을 알 수 있습니다."}}
rows[90976]={title={{19,524057128},"밴시 불러내기"},description={{90,1929444242},"밴시를 불러내 부상당한 SI:7 요원을 데려가게 합니다. 대상의 남은 생명력이 35% 이하여야 합니다."}}
