rows[91080]={title={{25,515629310},"아이템 - 떠도는 지속 피해 효과"},description={"^your harmful spells have a chance to afflict your victim with vengeful wisp, which deals ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. in addition, each time the vengeful wisp deals damage, it has a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to spread to a random nearby enemy%.$","해로운 주문 시전 시 일정 확률로 대상을 복수심에 불타는 위습에 감염시켜 \0312\031초마다 \0311\031의 피해를 입힙니다. 추가적으로 대상이 그 피해를 입을 때마다 \0313\031%의 확률로 주변 임의의 대상에 전염됩니다.",{0,0,0},{1,2,3}}}
