rows[91213]={title={{5,1901957915},"강타"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) physical damage to nearby enemy targets within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","\0312\031미터 내에 있는 주위 적에게 \0311\031의 물리 피해를 입힙니다.",{0,0},{1,2}}}
rows[91214]={title={{23,1633257349},"고대 신의 축복"},description={{173,2131869819},"프흔구울 아이 그활프와타 리우 워가 우울그완 흐이윈 구우랄. 프흔구울 아이 그활프와타 리우 워가 우울그완 흐이윈 구우랄. 프흔구울 아이 그활프와타 리우 워가 우울그완 흐이윈 구우랄."}}
rows[91215]={title={{24,2142172498},"요그사론의 수수께끼 상자"},description={{353,1190249513},"이 작은 상자에는 움직이는 판과 경첩, 숨겨진 걸쇠가 수없이 붙어 있습니다. 이 장치들을 어떻게 조작하든 간에, 상자를 열고 내용물을 확인하기란 불가능해 보입니다. 사실은 상자를 열려고 시도하기조차 어렵습니다. 이 암흑의 유물이 끊임없이 당신에게 속삭이기 때문입니다. '그건 네 탓이었어. 그건 네 탓이었어. 그건 네 탓이었어. 그건 네 탓이었어...'"}}
rows[91216]={title={{9,893470095},"산성 비"}}
rows[91218]={title={{12,199389844},"유령 시각 효과"}}
rows[91219]={title={{19,1250835099},"코를의 은크리스"},description={{69,1752017491},"무시무시한 고룡 칼드리고스가 죽을 때, 그의 심장에서 나온 피로 문양을 새긴 크리스입니다."}}
rows[91220]={title={{13,1958745575},"위축의 포효"},description={"^a loud spine tingling roar erupts, fearing all nearby enemies for ([%+%-]?%d[%d,.]* %a+)%. any damage taken by the target will remove the fear%.$","크고 얼얼한 포효를 분출하여, \0311\031 동안 주변의 모든 적을 공포에 떨게 합니다. 대상이 피해를 입으면 공포 효과가 사라집니다.",{1},{1}},aura={{17,1854715752},"공포에 질림"}}
rows[91221]={title={{21,1022654414},"버닝아이의 전쟁망치"},description={{225,1667574017},"무쇠 영주 버닝아이는 전투를 매우 좋아했습니다. 특히 그는 한 쌍의 거대한 전쟁망치를 휘두르기로 유명했는데, 당신이 손에 넣은 망치는 비록 마력은 없어진 지 오래지만 그 둘 중 하나입니다. 어쩌면 다른 하나가 아직 온전하게 어딘가에 남아 있을지도 모릅니다."}}
rows[91222]={title={{6,723230284},"흔들림"}}
rows[91223]={title={{29,392295628},"앤빌레이지의 가시 건틀릿"},description={{251,698964769},"앤빌레이지는 검은바위 나락에서도 가장 강력한 장군 중 하나였습니다. 그의 상징인 불타는 모루 표식을 오늘날까지도 검은바위 나락에서 찾아볼 수 있습니다. 이제 그는 저 세상에 있어 더는 검은무쇠 드워프 군대를 지휘할 수 없지만, 수많은 병사가 그의 이름을 지니고 있습니다."}}
rows[91224]={title={{19,1343083548},"여제 조이의 전언"},description={{405,1580004485},"여제 조이의 전언과 여제 조이의 서약은 강력한 한 쌍의 마법 반지입니다. 당신이 손에 넣은 반지인 \"전언\"은 안타깝게도 부서져 그 마력을 잃었습니다. \"서약\"은 어디로 갔는지 알 수 없지만, 어쩌면 아직 온전할지도 모릅니다. 여제 조이에 대해서는 검은무쇠 부족의 통치자라는 것 이외에 별로 알려진 바가 없습니다. 그녀는 용의 알이나 새끼용을 훔치는 데 집착했고, 많은 드워프가 그 집착을 웃음거리로 삼다가 죽임을 당했습니다."}}
rows[91225]={title={{22,428245617},"브론즈비어드의 홀"},description={{399,1857010560},"브론즈비어드란 드워프 부족 중 하나의 이름이자, 그 부족을 다스리는 가문을 가리키는 말이기도 합니다. 왕좌에 앉았던 브론즈비어드의 왕들은 통치 기간에 홀을 여러 번 바꾸었는데, 이는 왕이 조언자 중 가장 높은 이나 가장 중요한 동맹에게 하루 동안 홀을 내주는 전통이 있었기 때문입니다. 홀의 처지를 생각하면 참 불운한 날이라고 할 수 있습니다. 많은 홀이 이날 선술집을 구경하거나, 산꼭대기에서 떨어지거나, 트로그 따위의 머리를 내리치는 등의 일을 겪었으니까요."}}
rows[91226]={title={{24,1083118640},"여관주인의 딸"},description={{367,121675615},"전설에 따르면 브라이어 스톤키퍼는 모단 호수 근처에서 잘 나가는 여관을 운영했다고 합니다. 그의 딸 킬린은 집에서 멀리 여행을 떠나 유명세를 타게 되었는데, 아버지는 이것이 못마땅했습니다. 브라이어는 노움 흑마법사와 거래하여 딸을 집 근처에 잡아두려고 했습니다. 흑마법사는 킬린을 귀환석으로 변신시켜 언제나 여관으로 돌아오게 하였습니다."}}
rows[91227]={title={{34,621636380},"마술사 영주 타우릿산의 지팡이"},description={{447,835859871},"마술사 영주 타우릿산은 세 망치의 전쟁 때 검은무쇠 드워프의 지도자였습니다. 아이언포지를 브론즈비어드 부족에게 잃은 후, 타우릿산은 붉은마루 산맥까지 물러가 자신의 이름을 딴 도시를 세웠습니다. 필사적으로 적을 물리칠 방법을 찾던 타우릿산은 뜻하지 않게 반신 라그나로스를 불러냈고, 그 자리에서 바로 죽음을 맞고 말았습니다. 불 뿜는 검은바위 산의 봉우리들은 라그나로스가 아제로스에 현신함에 따라 생긴 것입니다."}}
