rows[91294]={title={{14,2115986416},"소용돌이 칼날"},description={"^attacks nearby enemies in a whirlwind of steel that lasts ([%+%-]?%d[%d,.]* %a+)%. and inflicts normal damage plus ([%+%-]?%d[%d,.%+%-to –]*)%.$","주위 적을 \0311\031 동안 지속되는 소용돌이 칼날로 공격하여 일반 피해를 입힙니다. 일반 공격력에 추가로 \0312\031의 피해를 입힙니다.",{1,0},{1,2}},aura={"^attacking all nearby enemies for normal damage plus ([%+%-]?%d[%d,.%+%-to –]*)%. rooted%.$","주위 모든 적에게 일반 공격력에 추가로 \0311\031의 피해\010휘감김",{0},{1}}}
