rows[91303]={title={{10,2133768640},"개종"},description={"^cho'gall beckons to the weak of mind causing the target to channel the worshipping spell on him%. worshipping cho'gall causes him to gain twisted devotion every ([%+%-]?%d[%d,.%+%-to –]*) sec%. worshipping can be interrupted%.$","초갈이 대상의 약점을 일깨워 자신을 숭배하게 만듭니다. 초갈은 숭배받는 동안 \0311\031초마다 뒤틀린 헌신 효과를 얻습니다. 숭배에는 정신 집중이 필요하며 방해받을 수 있습니다.",{0},{1}},aura={{24,197984336},"개종했습니다!"}}
