rows[91760]={title={{25,1296809847},"변신 견디기"},description={"^endure the transformation for ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031 동안 변신 과정을 견뎌 냅니다.",{1},{1}},aura={{12,99424883},"변신 중"}}
rows[91761]={title={{23,24195585},"변신의 뼈"},description={{342,792721047},"첫 번째 영원의 샘이 파괴되었을 때, 칼도레이 문명의 심장부도 함께 바다 밑으로 가라앉았습니다. 눈앞에 닥친 죽음을 피하고자 아즈샤라 여왕은 더 강한 힘을 지닌 어떤 존재, 아마도 고대 신 혹은 정령 군주와 계약을 맺었습니다. 그 결과 살아남은 명가의 일원들은 대대로 저주를 받아, 오늘날 나가라 불리는 뒤틀린 뱀 같은 생명체가 되었습니다."}}
rows[91762]={title={{28,59225199},"마도사 백 인의 목걸이"},description={{340,1824650670},"쿠엘탈라스의 엘프는 트롤 전쟁 때 아마니 트롤에게 거의 패배할 지경에 이르렀습니다. 필사적인 심정이 된 엘프는 아라소르의 인간에게 비전 마법을 가르쳤습니다. 엘프가 선발해서 가르친 인간은 겨우 백 명으로서, 이는 트롤을 물리치는 데 필요한 최소한의 인원이었습니다. 인간은 선천적으로 마법을 다루는 데 서툴었지만 마법에 대한 친화력이 매우 높았습니다."}}
rows[91763]={title={{13,741188253},"주문 수락"}}
rows[91764]={title={{12,2101857009},"투명 상태 보기 11"}}
rows[91765]={title={{12,2101857010},"투명 상태 보기 12"}}
rows[91766]={title={{18,1831322772},"은 두루마리 함"},description={{285,1847596748},"엘프가 만든 두루마리 함을 뒤덮은 화려한 장식도 눈길을 끌지만, 그보다도 더 흥미로운 것은 안에 든 내용입니다. 글귀는 나이트 엘프어로 쓰여 있습니다. '피라몬드, 어떤 상황에서든 그 선술집 여급 따위와 시간을 보내선 안 된다. 네 어머니와 나를 거역하지 마라. 그 여자는 너보다 지위가 한참 낮다.'"}}
rows[91767]={title={{12,2101857011},"투명 상태 보기 13"}}
rows[91768]={title={{13,1817518095},"아가타 소환"}}
rows[91769]={title={{14,1040923408},"초승달 본그림자"},description={{314,1097312125},"나이트 엘프 감시자들이 흔히 즐겨 쓰는 무기로서, 칼날이 둥글게 호를 그리고 있습니다. 마이에브 섀도송이 쓴 무기로 가장 유명하지만, 오늘날까지도 하이잘 산의 지하굴 감시자 등 많은 나이트 엘프가 이런 무기를 휘두릅니다. 당신의 손에 들어온 이 무기는 지금처럼 조각나기 전에는 강한 마력이 담긴 물건이었을 듯합니다."}}
rows[91770]={title={{15,186284861},"신호탄 01"}}
rows[91771]={title={{9,902275301},"위습 형상"},description={"^take on wisp form for ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031 동안 위습 형상으로 변신합니다.",{1},{1}},aura={{7,437465482},"위습 형상"}}
rows[91773]={title={{11,383166183},"위습 아뮬렛"},description={{383,1114394480},"위습은 나이트 엘프가 죽어 자연의 정령이 된 것이라고들 합니다. 위습은 자신이 거하는 숲, 그리고 나이트 엘프와 대체로 끈끈한 관계를 유지하며, 건설, 수리, 방어 등, 엘프들에게 도움이 되는 여러 가지 활동을 합니다. 3차 대전쟁 때 아키몬드를 물리치려고 많은 위습이 자신을 희생했기에, 지금은 예전보다 위습의 수가 적습니다."}}
rows[91774]={title={{27,840059094},"신호탄 01 처치 점수"}}
rows[91775]={title={{14,95817303},"모래성"},description={{261,508827576},"모래로 만들어진 사각형의 작은 요새입니다. 각진 탑과 태양 문양이 반복되는 것으로 보아 톨비르 건축 양식인 듯하지만, 울둠 안 어디에서도 이와 똑같이 설계된 곳은 보지 못했습니다. 사암이 아닌 모래로 만들어진 건 분명한데, 어떻게 허물어지지 않는지 모르겠습니다."}}
rows[91776]={title={{4,224427223},"할퀴기"},description={"^claw the enemy, dealing ([%+%-]?%d[%d,.%+%-to –]*)%% of normal melee damage%.$","적을 발톱으로 할퀴어 일반 근접 공격력의 \0311\031%에 해당하는 피해를 입힙니다.",{0},{1}}}
rows[91777]={title={{22,606873346},"티리스팔 수호자 오라"}}
rows[91778]={title={{14,131135396},"발톱 휩쓸기"}}
rows[91779]={title={{28,1231300194},"에메랄드 눈이 달린 고양이 조각상"},description={{145,2135315269},"이 작은 조각상은 살아 있는 것 같은 자세와 표정을 지니고 있습니다. 조각상 아래에는 다음 글귀가 새겨져 있습니다. '닌즈테르 황제 폐하의 사랑스러운 애완동물, 찰릭스를 추억하며'"}}
rows[91780]={title={{25,1799468540},"비누돌 스카라베 목걸이"},description={{103,22202660},"'닌즈테르 황제 폐하가 왕위에 오르시던 날 진상됨. 폐하의 위대한 통치를 열망하며.'"}}
rows[91781]={title={{15,186284862},"신호탄 02"}}
rows[91782]={title={{17,1879613660},"아주 작은 오아시스 모자이크"},description={{236,1735402288},"이 작은 예술 작품은 밝은 청록색, 초록색, 모래 색깔의 점토 조각으로 구성되었습니다. '닌즈테르 황제 폐하께 우리의 희망과 기도를. 기근을 끝내고 람카헨의 영광을 되찾아 주시기를!'"}}
rows[91783]={title={{15,186284863},"신호탄 03"}}
rows[91784]={title={{27,1142049958},"신호탄 02 처치 점수"}}
rows[91785]={title={{22,1998028639},"글이 새겨진 시미터 칼자루"},description={{299,56568760},"이 시미터는 무기라기보다 장식물에 가까워 보입니다. 그리 길지 않은 칼날이 달렸지만, 전투에서 위력을 발휘할 것처럼 보이지는 않습니다. 칼머리 장식에서부터 시작되어 자루를 휘감고 내려오는 문구가 새겨져 있습니다. 내용은 다음과 같습니다. '닌즈테르 황제여, 우리를 승리로 이끄소서! 카데쉬! 오사디! 사테크!'"}}
rows[91786]={title={{15,2074258112},"대상 목조르기"},description={{38,520195975},"대상을 붙잡아 안으로 끌어갑니다."}}
rows[91787]={title={{29,540184971},"플린트로크의 폭발물 설치"},description={{62,280890705},"하늘절단호의 심장부에 플린트로크의 폭발물을 설치합니다."}}
rows[91788]={title={{10,1671366895},"포탄"},description={{71,680870052},"적에게 포탄을 발사하여 큰 피해를 입히고 기절시킵니다."},aura={{8,318235535},"기절함"}}
rows[91790]={title={{11,1170254125},"유골 단지"},description={{141,1976213116},"이 단지에는 닌즈테르 황제의 석화된 장기가 담겨 있습니다. 닌즈테르의 통치 기간에 톨비르는 영화를 누리리라 예견되었으나, 그는 통치를 시작한 지 몇 년 안 되어 죽고 만 듯합니다."}}
rows[91791]={title={{8,1010387266},"목조르기"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*)%% damage per second%.$","1초마다 \0311\031%의 피해를 입힙니다.",{0},{1}}}
rows[91792]={title={{25,1923802281},"사막 궁전의 밑그림"},description={{244,602798678},"건축가가 아주 웅장한 규모로 구상하여 그린 건축 도안입니다. 지금의 울둠에서 는 이 궁전과 비슷한 구조물을 볼 수 없기에, 아마도 실제 지어지지는 않은 것 같습니다. '황제 닌즈테르의 명으로' 제작되었습니다."}}
rows[91793]={title={{29,1626189359},"프랑클론 포지라이트의 담뱃대"},description={{232,717907453},"포지라이트는 검은무쇠 부족의 유명한 건축가였습니다. 그는 수많은 건축을 감독했지만, 그중에서도 돌다지 댐과 검은바위 나락의 많은 구역을 감독했음이 가장 잘 알려졌습니다. 검은바위 산에는 아직도 그의 유령이 출몰한다는 소문이 돕니다."}}
rows[91794]={title={{27,1444040822},"신호탄 03 처치 점수"}}
rows[91795]={title={{30,2125902920},"하늘절단호 장식용 폭발"}}
rows[91797]={title={{14,33437219},"무시무시한 일격"},description={"^strike an enemy with a smashing attack, dealing ([%+%-]?%d[%d,.%+%-to –]*)%% of normal melee damage and stunning for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 강타를 날려 일반 근접 공격력의 \0311\031%에 해당하는 피해를 입히고 \0312\031 동안 기절시킵니다.",{0,1},{1,2}},aura={{8,318235535},"기절함"}}
rows[91800]={title={{4,233453909},"물어뜯기"},description={"^bite and tear at a target's limbs, stunning it for ([%+%-]?%d[%d,.]* %a+) and dealing damage%.$","대상의 사지를 이로 깨물어 \0311\031 동안 기절시키고 피해를 입힙니다.",{1},{1}},aura={{8,318235535},"기절함"}}
rows[91801]={title={{13,1108149404},"필사의 일격"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage and leaves the target wounded, reducing the effectiveness of any healing by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 무기 공격력의 \0311\031%에 해당하는 피해를 입히고 \0313\031 동안 상처를 남겨 해당 대상이 받는 치유 효과를 \0312\031%만큼 감소시킵니다.",{0,0,1},{1,2,3}},aura={"^healing effects reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","치유 효과 \0311\031%만큼 감소",{0},{1}}}
rows[91802]={title={{14,2024708251},"휘청거리는 돌격"},description={"^charge an enemy, interrupting spellcasting and immobilizing them for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 돌진하여 주문 시전을 차단하고 \0311\031 동안 이동 불가 상태로 만듭니다.",{1},{1}}}
rows[91804]={title={{16,1653506855},"어둠의 서약"},description={{56,2134554278},"암흑의 자수정 잔류물을 방출하여 암흑 피해를 입힙니다."}}
rows[91807]={title={{14,2024708251},"휘청거리는 돌격"},description={"^charge an enemy, interrupting spellcasting and immobilizing them for ([%+%-]?%d[%d,.]* %a+)%.$","적에게 돌진하여 주문 시전을 차단하고 \0311\031 동안 이동 불가 상태로 만듭니다.",{1},{1}},aura={{12,1673095295},"이동 불가"}}
rows[91808]={title={{13,656017193},"주문 포기"}}
rows[91809]={title={{4,244539908},"도약"},description={{28,1835617300},"적 대상의 배후로 도약합니다."}}
