rows[91814]={title={{20,1201308118},"아이템 - 힘 효과"},description={"^your melee attacks have a chance to grant ([%+%-]?%d[%d,.%+%-to –]*) strength for ([%+%-]?%d[%d,.]* %a+)%.$","근접 공격 시 일정 확률로 \0312\031 동안 힘이 \0311\031만큼 증가합니다.",{0,1},{1,2}}}
rows[91815]={title={{13,694244247},"타오르는 보호막"},description={{135,1095104910},"시전자를 마법 공격으로부터 보호하고 주위 모든 적에게 화염 피해를 입힙니다. 받는 마법 피해가 50%만큼 감소합니다."},aura={{73,440433413},"마법 피해 50%만큼 감소\010주위 적에게 화염 피해"}}
