rows[93150]={title={{10,408137882},"완력의 부적"},description={"^increases health by ([%+%-]?%d[%d,.%+%-to –]*) for ([%+%-]?%d[%d,.]* %a+)%. this magic only works in winterspring%.$","\0312\031 동안 생명력을 \0311\031만큼 증가시킵니다. 여명의 설원에서만 사용할 수 있습니다.",{0,1},{1,2}},aura={"^health increased by ([%+%-]?%d[%d,.%+%-to –]*)%. this magic only works in winterspring%.$","생명력 \0311\031만큼 증가. 여명의 설원에서만 사용 가능.",{0},{1}}}
