rows[97844]={title={{15,8019234},"주먹 세례"},description={"^bashes rapidly at the enemy for ([%+%-]?%d[%d,.]* %a+)%. duration increases by ([%+%-]?%d[%d,.%+%-to –]*)%% per chi%.$","\0311\031 동안 대상에게 세찬 맹공격을 가합니다.\010\010기 1당 지속시간이 \0312\031%만큼 증가합니다.",{1,0},{1,2}},aura={{18,760826449},"맹공격 중"}}
