rows[97846]={title={{14,1936732014},"폭렬장"},description={"^strike the enemy, causing ([%+%-]?%d[%d,.%+%-to –]*) %(%+0%.1 ap%) fire damage plus ([%+%-]?%d[%d,.%+%-to –]*) fire damage per chi and stuns the target for ([%+%-]?%d[%d,.]* %a+)%. duration increases by ([%+%-]?%d[%d,.%+%-to –]*)%% per chi%.$","적을 가격하여 \0311\031 (+0.1 AP)의 화염 피해에 추가로 기 1당 \0312\031만큼 화염 피해를 입히고 \0313\031 동안 대상을 기절시킵니다.\010\010기 1당 지속시간이 \0312\031%만큼 증가합니다.",{0,0,1,0},{1,2,3,2}},aura={{8,318235535},"기절함"}}
rows[97847]={title={{20,481026396},"광풍각"},description={"^knocks away all nearby enemies, reducing their attack speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","주위 모든 적을 뒤로 밀쳐내고, 공격 속도를 \0311\031%만큼 감소시킵니다.",{0},{1}},aura={"^time between attacks increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격 간격 \0311\031%만큼 증가",{0},{1}}}
