rows[97857]={title={{13,1979537071},"불새의 화염"},description={"^send a flaming phoenix towards the target, causing ([%+%-]?%d[%d,.%+%-to –]*) fire damage and burns the target, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage every ([%+%-]?%d[%d,.%+%-to –]*) sec and reduces healing received by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","타오르는 불새를 날려보냅니다. 불새는 대상을 불태워 \0311\031의 화염 피해를 입히고 \0313\031초마다 \0312\031의 추가 화염 피해를 입히며, \0315\031 동안 받는 치유 효과를 \0314\031%만큼 감소시킵니다.",{0,0,0,0,1},{1,2,3,4,5}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) fire damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. healing received reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0312\031초마다 \0311\031의 화염 피해\010받는 치유 효과 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
