rows[97978]={title={{16,1160872232},"고대의 수호자"},description={"^bless the target with the power of ancient zandalari guardians%. any attack which would otherwise kill the target will instead bring it to ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health%.$","대상에게 고대 잔달라 수호자의 축복을 내립니다. 대상이 죽음에 다다를 수 있는 공격을 받으면 최대 생명력의 \0311\031%만큼을 회복합니다.",{0},{1}},aura={"^attacks which would otherwise kill you will instead restore ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health%.$","죽음에 다다를 수 있는 공격을 받으면 최대 생명력의 \0311\031%만큼을 회복",{0},{1}}}
