rows[97983]={title={{15,893895431},"수호 영혼"},description={"^calls upon a guardian spirit to watch over the friendly target%. the spirit increases the healing received by the target by ([%+%-]?%d[%d,.%+%-to –]*)%%, and also prevents the target from dying by sacrificing itself%. this sacrifice terminates the effect but heals the target of ([%+%-]?%d[%d,.%+%-to –]*)%% of their maximum health%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","수호 영혼을 불러내어 아군 대상을 보호하게 합니다. 수호 영혼은 대상이 받는 치유 효과를 \0311\031%만큼 증가시키고 자신을 희생하여 대상을 죽음으로부터 보호합니다. 희생 시 효과는 사라지고 대상의 최대 생명력의 \0312\031%에 해당하는 생명력을 회복시킵니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^increased healing received by ([%+%-]?%d[%d,.%+%-to –]*)%% and will prevent 1 killing blow%.$","받는 치유 효과 \0311\031%만큼 증가\0101회의 결정타에서 대상을 보호",{0},{1}}}
