rows[98006]={title={{14,1075438592},"불꽃의 인장"},description={"^place a sigil on the target, dealing ([%+%-]?%d[%d,.%+%-to –]*) fire damage every ([%+%-]?%d[%d,.%+%-to –]*) seconds for ([%+%-]?%d[%d,.]* %a+)%. when shattered, deals additional fire damage over time to the target%.$","대상에게 인장을 사용하여 \0313\031에 걸쳐 \0312\031초마다 \0311\031의 화염 피해를 입힙니다. 인장이 부서지면 대상은 지속적인 추가 화염 피해를 입습니다.",{0,0,1},{1,2,3}},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) fire damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. if shattered, deals additional fire damage over time to the target%.$","\0312\031초마다 \0311\031의 화염 피해\010부서지면 대상에게 지속적인 추가 화염 피해",{0,0},{1,2}}}
rows[98007]={title={{17,1781273284},"정신의 고리 토템"},description={"^the spirit link totem reduces damage taken by all party and raid members within ([%+%-]?%d[%d,.%+%-to –]*) yards by ([%+%-]?%d[%d,.%+%-to –]*)%%%. every ([%+%-]?%d[%d,.%+%-to –]*) sec, the health of all affected players is redistributed, such that each player ends up with the same percentage of their maximum health%.$","주위 \0311\031미터 반경 내의 모든 파티원과 공격대원이 받는 피해를 \0312\031%만큼 감소시킵니다. 효과를 입은 모든 플레이어의 생명력이 \0313\031초마다 재분배되어 모든 플레이어가 최대 생명력의 같은 비율을 지니게 됩니다.",{0,0,0},{1,2,3}},aura={"^damage taken reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. health periodically normalized among other affected party and raid members%.$","받는 피해 \0311\031%만큼 감소\010효과를 입은 모든 파티원 혹은 공격대원의 생명력이 주기적으로 재분배됨",{0},{1}}}
