rows[98448]={title={{9,2011151924},"기 폭발"},description={"^hurls a massive orb of chi at a target location, dealing ([%+%-]?%d[%d,.%+%-to –]*) holy damage to all enemies within 10 yards%. doesn't break crowd control effects%.$","대상을 향해 기의 구슬을 다량으로 날려보내, 반경 10미터 안의 모든 적에게 \0311\031의 신성 피해를 입힙니다. 군중 제어 효과를 깨뜨리지 않습니다.",{0},{1}}}
