rows[98450]={title={{13,484397629},"불타는 씨앗"},description={"^implants fiery seeds in the caster's enemies%. each seed grows at a different rate%. when fully grown the seeds explode, inflicting ([%+%-]?%d[%d,.%+%-to –]*) fire damage to targets within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","적에게 불타는 씨앗을 심습니다. 씨앗은 각각 다른 속도로 자라며, 완전히 자라면 폭발하여 \0312\031미터 반경 내의 대상에게 \0311\031의 화염 피해를 입힙니다.",{0,0},{1,2}},aura={"^explodes after a period of time, causing ([%+%-]?%d[%d,.%+%-to –]*) fire damage to friends within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","일정 시간이 지나면 폭발하여 \0312\031미터 반경 내의 아군에게 \0311\031의 화염 피해",{0,0},{1,2}}}
