rows[98532]={title={{12,1843462549},"늑대인간 타락"},description={"^target becomes a temporary victim of the worgen curse%. while transformed, melee, ranged, and spell%-casting speed is increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, but armor is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","대상에게 일시적으로 늑대인간의 저주를 겁니다. 변신한 동안에는 근접 및 원거리 공격, 주문 시전 속도가 \0311\031%만큼 증가하지만 방어도가 \0312\031%만큼 감소합니다.",{0,0},{1,2}},aura={"^time between melee and ranged attacks reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. casting speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. armor reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","근접 및 원거리 공격 간격 \0311\031%만큼 감소\010시전 속도 \0311\031%만큼 증가\010방어도 \0313\031%만큼 감소",{0,0,0},{1,1,3}}}
rows[98533]={title={{20,863235143},"멸종된 거북 등딱지"},description={{292,1452194795},"거북은 오랜 시간에 걸쳐 약간의 변화만 겪은 고대 생명체입니다. 거북은 크게 3종으로 나뉘는데 거기에는 바다거북, 민물에 사는 남생이, 깨끗한 물에 사는 테라핀이 있습니다. 그중 남생이의 것으로 보이는 이 단단한 등딱지를 사용하면 아주 훌륭한, 하지만 약간은 우스꽝스러워 보이는 방패를 만들 수 있을 것입니다."}}
