rows[98535]={title={{14,1974199691},"화염 도약"},description={"^fandral leaps at an enemy, leaving behind a spirit of the flame%. he lands in a blaze of glory, igniting the ground at his destination and causing it to burn enemy enemy units for ([%+%-]?%d[%d,.%+%-to –]*) fire damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","판드랄이 적에게 달려듭니다. 그가 원래 있던 자리에는 화염의 영혼이 생깁니다. 판드랄은 목표 지점에 도달하면 영광의 빛을 내뿜으며 땅을 불태워, 적에게 \0313\031 동안 \0312\031초마다 \0311\031의 화염 피해를 입힙니다.",{0,0,1},{1,2,3}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) fire damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 화염 피해",{0,0},{1,2}}}
